      id: 'full-name',
      label: 'Full Name',
      type: 'text',
      required: true,
      placeholder: 'Jane Smith',
      autocomplete: 'name',
      errorText: 'Full name is required.',
      errorTextId: 'full-name-error',
    },
    {
      id: 'email',
      label: 'Email Address',
      type: 'email',
      required: true,
      placeholder: 'jane@example.com',
      autocomplete: 'email',
      errorText: 'A valid email address is required.',
      errorTextId: 'email-error',
    },
    {
      id: 'phone',
      label: 'Phone Number',
      type: 'tel',
      optional: true,
      placeholder: '+1 (555) 000-0000',
      autocomplete: 'tel',
      helperText: 'Enter your number in international format, e.g. +1 (555) 000-0000.',
      helperTextId: 'phone-helper',
    },
  ];

  const successBanner = SuccessBanner();

  const formFieldEls = fields.map(f => FormField(f));

  const submitBtn = createEl('button', {
    type: 'submit',
    className: 'btn-submit',
  }, 'Send Message');

  const formActions = createEl('div', { className: 'form-actions' }, submitBtn);

