    fields.forEach(field => {
      if (!field.required) return;
      const input = form.querySelector(`#${field.id}`);
      const errorEl = field.errorTextId ? form.querySelector(`#${field.errorTextId}`) : null;

      const value = input.value.trim();
      let fieldValid = true;

      if (field.type === 'email') {
        fieldValid = value !== '' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
      } else {
        fieldValid = value !== '';
      }

      if (!fieldValid) {
        valid = false;
        input.classList.add('is-invalid');
        input.setAttribute('aria-invalid', 'true');
        if (errorEl) errorEl.classList.add('visible');
      } else {
        input.classList.remove('is-invalid');
        input.removeAttribute('aria-invalid');
        if (errorEl) errorEl.classList.remove('visible');
      }
    });

    if (valid) {
      form.reset();
      // Clear any residual error states
      form.querySelectorAll('input').forEach(inp => {
        inp.classList.remove('is-invalid');
        inp.removeAttribute('aria-invalid');
      });
      form.querySelectorAll('.field-error').forEach(err => err.classList.remove('visible'));

      successBanner.classList.add('visible');
      successBanner.focus();
    } else {
      successBanner.classList.remove('visible');
      const firstInvalid = form.querySelector('.is-invalid');
      if (firstInvalid) firstInvalid.focus();
    }
  }

  // Clear error state on input
  fields.forEach(field => {
    if (!field.required) return;
    const input = form.querySelector(`#${field.id}`);
    const errorEl = field.errorTextId ? form.querySelector(`#${field.errorTextId}`) : null;
    input.addEventListener('input', () => {
      if (input.classList.contains('is-invalid')) {
        input.classList.remove('is-invalid');
        input.removeAttribute('aria-invalid');
        if (errorEl) errorEl.classList.remove('visible');
      }
    });
  });

  const card = createEl('div', { className: 'card' }, successBanner, form);
  return card;
}

function App() {
  const wrapper = createEl('div', { className: 'page-wrapper' },
    PageHeader(),
    ContactForm()
  );
  return wrapper;
}

