      errorTextId: 'full-name-error',
    },
    {
      id: 'email',
      label: 'Email Address',
      type: 'email',
      required: true,
      placeholder: 'jane@example.com',
      autocomplete: 'email',
      errorText: 'A valid email address is required.',
      errorTextId: 'email-error',
